-- ============================================================================
-- B5 FOLLOW-ON W3 (Suite Full precision): carbon capstone brief.
--
-- Plan of record: docs/graded-field-audit/FOLLOW-ON-PROGRAMME.md section 2 and
-- the section 1 Suite rows, decision D3 (owner approved D1 to D7 as
-- recommended, 2026-09-21). The Suite app the capstone is read in gains a
-- "Full precision" switch, off by default, that prints the graded quantities
-- at the precision they are graded to. The brief now says to switch it on.
--
-- INTERMEDIATE
--   Fields read with the switch on: igrita_efficiency_lhv_pct.
--   The headline rounds the efficiency to 2 decimals; the prompt asks 4 at tol
--   1e-4.
--   APPENDED: Read the figures in the Energy & Utilities Efficiency Studio with
--   its Full precision switch on (at the top of the page): it prints them to the
--   precision this capstone grades, with no digit grouping.
--
-- WHAT DOES NOT MOVE. `fields` (every key, label, unit, expected and
-- tolerance, and their order), title, dataset, status and the row. The guard
-- requires `fields` to equal its post-W1 value exactly, before and after, so
-- no answer grades differently and no attempts guard is needed.
--
-- ORDER. Apply only once the Suite build carrying the W3 switch is live (the
-- brief names it). Runs after W1 (20261024*): refuses without it.
--
-- GUARDS. Each prompt must hold its post-W1 text (md5, rewritten) or its W3
-- text (left alone), with the exact fields. Anything else raises and the file
-- rolls back. Generated by docs/graded-field-audit/w3_capstones.py from
-- w3/carbon.json. SAFE TO RE-RUN: a second run writes nothing.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_s0       text;
begin
  -- carbon / intermediate
  select count(*) into v_n from public.academy_capstones where app_slug = 'carbon' and tier = 'intermediate' and active;
  if v_n <> 1 then raise exception 'w3 carbon refused: carbon/intermediate has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = 'af4b4bfaf90d69a894d832e90dd40662' and fields = '[{"key": "igrita_excess_air_pct", "tol": 0.0001, "unit": "percent", "label": "Excess air at the current oxygen", "expected": 37.86451}, {"key": "igrita_efficiency_lhv_pct", "tol": 0.0001, "unit": "percent", "label": "Heater efficiency on LHV at the current oxygen", "expected": 85.021597}, {"key": "igrita_tuning_saving_gj", "tol": 1, "unit": "GJ a year", "label": "Fuel saved a year by tuning to the target oxygen", "expected": 7771.999995}, {"key": "igrita_trap_t_per_yr", "tol": 0.01, "unit": "t a year", "label": "Steam lost through the failed trap", "expected": 469.68800466}, {"key": "igrita_pinch_hot_utility_kw", "tol": 0.01, "unit": "kW", "label": "Minimum hot utility", "expected": 51.59}, {"key": "igrita_pinch_cold_utility_kw", "tol": 0.01, "unit": "kW", "label": "Minimum cold utility", "expected": 224.13}]'::jsonb then 'old'
              when md5(prompt) = '8914120ed219a4f5d485bcedc9d4b097' and fields = '[{"key": "igrita_excess_air_pct", "tol": 0.0001, "unit": "percent", "label": "Excess air at the current oxygen", "expected": 37.86451}, {"key": "igrita_efficiency_lhv_pct", "tol": 0.0001, "unit": "percent", "label": "Heater efficiency on LHV at the current oxygen", "expected": 85.021597}, {"key": "igrita_tuning_saving_gj", "tol": 1, "unit": "GJ a year", "label": "Fuel saved a year by tuning to the target oxygen", "expected": 7771.999995}, {"key": "igrita_trap_t_per_yr", "tol": 0.01, "unit": "t a year", "label": "Steam lost through the failed trap", "expected": 469.68800466}, {"key": "igrita_pinch_hot_utility_kw", "tol": 0.01, "unit": "kW", "label": "Minimum hot utility", "expected": 51.59}, {"key": "igrita_pinch_cold_utility_kw", "tol": 0.01, "unit": "kW", "label": "Minimum cold utility", "expected": 224.13}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'carbon' and tier = 'intermediate' and active;
  if v_s0 = 'other' then
    raise exception 'w3 carbon refused: carbon/intermediate matches neither its post-W1 form (prompt md5 af4b4bfaf90d69a894d832e90dd40662) nor its W3 form (prompt md5 8914120ed219a4f5d485bcedc9d4b097), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W3 form
  if v_s0 = 'new' then
    raise notice 'w3 carbon: 0 of 1 row(s) written, all already applied';
    return;
  end if;

  -- W1 (20261024*) must be applied first: its rows are this file's base
  if not exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                  where c.app_slug = 'seismolord' and c.tier = 'intermediate' and c.active and f->>'key' = 'corr_zero_lag')
     or not exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                  where c.app_slug = 'mbal' and c.tier = 'beginner' and c.active and f->>'key' = 'eo_last_rb_stb')
     or not exists (select 1 from public.academy_capstones
                  where app_slug = 'basin' and tier = 'beginner' and active and prompt like 'Open book%') then
    raise exception 'w3 carbon refused: W1 (20261024*) is not applied on this database; apply it first (/root/w1-apply/apply.sh apply --prod)';
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'IGRITA GAS CONDITIONING PLANT, Aluu Gas Services Ltd (an invented record; every figure is invented for the course). The fired heater burns a fuel gas of mole fractions CH4 0.912, C2H6 0.041, C3H8 0.012, CO2 0.021, N2 0.014, with the typical heating values the Efficiency Studio carries for each component. Stack 251 C, combustion air 31 C, a radiation and convection loss of 2.1 percent from the vendor''s chart, no unburned loss, the Studio''s typical flue gas and vapour specific heats and latent heat, efficiency on LHV. The dry stack oxygen reads 6.2 percent; a combustion test has declared 2.4 percent the minimum safe oxygen, and the plan is to tune to 3.1 percent. The heater burns 365000 GJ of fuel a year on LHV. A steam trap has failed open: a 5 mm orifice, the steam upstream at 7.2 bar on the gauge with the local atmosphere at 1.013 bar, a discharge coefficient of 0.68, dry saturated steam of density 4.28 kg/m3 and isentropic exponent 1.135, in service 8200 hours a year. Four process streams, at a minimum approach of 12 C: H1 regeneration gas cooler from 187 C to 55 C at 2.72 kW/K; H2 lean amine cooler from 124 C to 46 C at 6.3 kW/K; C1 rich amine preheat from 36 C to 161 C at 4.55 kW/K; C2 fuel gas heater from 29 C to 88 C at 1.85 kW/K. Give six numbers. (1) The excess air at the current oxygen, in percent, to four decimals. (2) The heater''s efficiency on LHV at the current oxygen, in percent, to four decimals. (3) The fuel saved a year by tuning to the target oxygen, in GJ, to the nearest whole GJ. (4) The steam lost through the trap in tonnes a year, to two decimals. (5) The minimum hot utility in kW, to two decimals. (6) The minimum cold utility in kW, to two decimals. Read the figures in the Energy & Utilities Efficiency Studio with its Full precision switch on (at the top of the page): it prints them to the precision this capstone grades, with no digit grouping.'
     where app_slug = 'carbon' and tier = 'intermediate' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w3 carbon refused: carbon/intermediate updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '8914120ed219a4f5d485bcedc9d4b097' and fields = '[{"key": "igrita_excess_air_pct", "tol": 0.0001, "unit": "percent", "label": "Excess air at the current oxygen", "expected": 37.86451}, {"key": "igrita_efficiency_lhv_pct", "tol": 0.0001, "unit": "percent", "label": "Heater efficiency on LHV at the current oxygen", "expected": 85.021597}, {"key": "igrita_tuning_saving_gj", "tol": 1, "unit": "GJ a year", "label": "Fuel saved a year by tuning to the target oxygen", "expected": 7771.999995}, {"key": "igrita_trap_t_per_yr", "tol": 0.01, "unit": "t a year", "label": "Steam lost through the failed trap", "expected": 469.68800466}, {"key": "igrita_pinch_hot_utility_kw", "tol": 0.01, "unit": "kW", "label": "Minimum hot utility", "expected": 51.59}, {"key": "igrita_pinch_cold_utility_kw", "tol": 0.01, "unit": "kW", "label": "Minimum cold utility", "expected": 224.13}]'::jsonb) from public.academy_capstones where app_slug = 'carbon' and tier = 'intermediate' and active) is not true then
    raise exception 'w3 carbon refused: carbon/intermediate does not read back as its W3 form';
  end if;

  raise notice 'w3 carbon: % of 1 row(s) written, % already applied', v_written, 1 - v_written;
end $$;
